write('server/engine/LivingWorldAI.mjs', r'''// MOR'IA 9.8 — authoritative living-world AI policy.
const clamp=(v,a,b)=>Math.max(a,Math.min(b,Number(v)||0));
const dist=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
const DIRS=Object.freeze([{x:1,y:0},{x:-1,y:0},{x:0,y:1},{x:0,y:-1}]);
const hash=s=>{let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0};
function seededChoice(id,tick,list){return list[(hash(id)+tick)%list.length]}
function normalizePoint(p,fallback={x:40,y:40}){return {x:Math.floor(Number(p?.x)||fallback.x),y:Math.floor(Number(p?.y)||fallback.y)}}
function hourOf(snapshot){return Number.isFinite(Number(snapshot?.hour))?Number(snapshot.hour):new Date().getUTCHours()}
function isOpen(npc,hour){const open=clamp(npc?.openHour??0,0,23), close=clamp(npc?.closeHour??24,1,24);return open<close?hour>=open&&hour<close:hour>=open||hour<close}
function walkable(map,x,y,occupied=new Set()){return Boolean(map?.tiles?.[y]?.[x]?.walkable&&!occupied.has(`${x},${y}`))}
function stepToward(from,to,map,occupied){const dx=Math.sign(to.x-from.x),dy=Math.sign(to.y-from.y);const primary=Math.abs(to.x-from.x)>=Math.abs(to.y-from.y)?[{x:dx,y:0},{x:0,y:dy}]:[{x:0,y:dy},{x:dx,y:0}];for(const d of primary){if((d.x||d.y)&&walkable(map,from.x+d.x,from.y+d.y,occupied))return {x:from.x+d.x,y:from.y+d.y}}return from}
function stepAway(from,threat,map,occupied){const choices=DIRS.map(d=>({x:from.x+d.x,y:from.y+d.y})).filter(p=>walkable(map,p.x,p.y,occupied)).sort((a,b)=>dist(b,threat)-dist(a,threat));return choices[0]||from}

class LivingWorldAI {
  constructor(){this.npcState=new Map();this.lastNpcTick=0}
  sync(contentDB){
    const seen=new Set();
    for(const npc of contentDB?.get?.('npcs')||[]){if(!npc?.id)continue;seen.add(npc.id);const prev=this.npcState.get(npc.id);const home={x:Number(npc.posX)||40,y:Number(npc.posY)||40};this.npcState.set(npc.id,{id:npc.id,mapId:npc.mapId,x:prev?.x??home.x,y:prev?.y??home.y,home,mode:prev?.mode||'idle',routeIndex:prev?.routeIndex||0,open:true,lastMove:prev?.lastMove||0})}
    for(const id of this.npcState.keys())if(!seen.has(id))this.npcState.delete(id);
  }
  routineFor(npc,clock){const h=hourOf(clock);const open=isOpen(npc,h);const schedule=Array.isArray(npc.schedule)?npc.schedule:[];const scheduled=schedule.find(s=>h>=Number(s.startHour??0)&&h<Number(s.endHour??24));return {open,mode:scheduled?.mode||(!open?'home':npc.aiMode||npc.role==='guard'?'patrol':'idle'),target:scheduled?.target||null}}
  tickNpcs({contentDB,world,clock,players=[],monstersByMap=new Map(),now=Date.now()}){
    if(now-this.lastNpcTick<350)return;this.lastNpcTick=now;this.sync(contentDB);
    const npcDefs=new Map((contentDB.get('npcs')||[]).map(n=>[n.id,n]));
    for(const state of this.npcState.values()){
      const npc=npcDefs.get(state.id);const map=world.getMap(state.mapId);if(!npc||!map)continue;const r=this.routineFor(npc,clock);state.open=r.open;state.mode=r.mode;
      const delay=clamp(npc.moveDelay??1100,250,10000);if(now-state.lastMove<delay)continue;
      const occupied=new Set();for(const p of players)if(p.mapId===state.mapId)occupied.add(`${p.x},${p.y}`);for(const m of monstersByMap.get(state.mapId)||[])if(!m.dead)occupied.add(`${m.x},${m.y}`);
      let next={x:state.x,y:state.y};
      if(npc.role==='guard'){
        const threat=(monstersByMap.get(state.mapId)||[]).filter(m=>!m.dead&&dist(state,m)<=clamp(npc.guardRadius??7,2,16)).sort((a,b)=>dist(state,a)-dist(state,b))[0];if(threat){state.mode='guard';next=stepToward(state,threat,map,occupied)}
      }
      if(next.x===state.x&&next.y===state.y){
        const route=Array.isArray(npc.patrolRoute)?npc.patrolRoute:[];
        if((state.mode==='patrol'||state.mode==='work')&&route.length){const target=normalizePoint(route[state.routeIndex%route.length],state.home);if(dist(state,target)===0)state.routeIndex=(state.routeIndex+1)%route.length;next=stepToward(state,target,map,occupied)}
        else if(state.mode==='home'&&!r.open)next=stepToward(state,state.home,map,occupied);
        else if(state.mode==='wander'){const d=seededChoice(state.id,Math.floor(now/delay),DIRS),p={x:state.x+d.x,y:state.y+d.y};if(walkable(map,p.x,p.y,occupied)&&dist(p,state.home)<=clamp(npc.wanderRadius??4,1,10))next=p}
      }
      if(walkable(map,next.x,next.y,occupied)){state.x=next.x;state.y=next.y}state.lastMove=now;
    }
  }
  publicNpcs(mapId,contentDB){const defs=new Map((contentDB.get('npcs')||[]).map(n=>[n.id,n]));return [...this.npcState.values()].filter(s=>s.mapId===mapId).map(s=>{const n=defs.get(s.id)||{};return {id:s.id,name:n.name,emoji:n.emoji,color:n.color,role:n.role,x:s.x,y:s.y,mode:s.mode,open:s.open}})}
  decideMonsterMove(monster,target,{map,occupied=new Set(),now=Date.now(),allies=[]}={}){
    const home={x:Number(monster.spawnX)||monster.x,y:Number(monster.spawnY)||monster.y};const leash=clamp(monster.leashRadius??12,4,30);const aggro=clamp(monster.aggroRadius??8,2,20);const d=target?dist(monster,target):Infinity;
    if(dist(monster,home)>leash)return {...stepToward(monster,home,map,occupied),mode:'return'};
    const hpRatio=(Number(monster.hp)||0)/Math.max(1,Number(monster.maxHp)||1);const archetype=monster.aiArchetype||monster.type||'normal';
    if(target&&hpRatio<=clamp(monster.fleeAtHp??(archetype==='normal'?0.12:0),0,0.8))return {...stepAway(monster,target,map,occupied),mode:'flee'};
    if(target&&d<=aggro){if(archetype==='pack'||monster.packId){const friend=allies.filter(a=>a.id!==monster.id&&!a.dead&&(a.packId===monster.packId||a.name===monster.name)).sort((a,b)=>dist(a,target)-dist(b,target))[0];if(friend&&dist(friend,target)>d+2)return {...stepToward(monster,friend,map,occupied),mode:'pack'}}return {...stepToward(monster,target,map,occupied),mode:'chase'}}
    const radius=clamp(monster.patrolRadius??3,0,8);if(radius>0){const d0=seededChoice(monster.id,Math.floor(now/Math.max(400,monster.speed||900)),DIRS),p={x:monster.x+d0.x,y:monster.y+d0.y};if(walkable(map,p.x,p.y,occupied)&&dist(p,home)<=radius)return {...p,mode:'patrol'}}return {x:monster.x,y:monster.y,mode:'idle'};
  }
  phase(monster){if(monster.type!=='boss')return 0;const ratio=(Number(monster.hp)||0)/Math.max(1,Number(monster.maxHp)||1);return ratio<=.25?3:ratio<=.5?2:ratio<=.75?1:0}
}
export const livingWorldAI=new LivingWorldAI();
''')

write('server/engine/CombatDepth.mjs', r'''// MOR'IA 9.8 — telegraphs, stagger, interrupts and bounded status effects.
const clamp=(v,a,b)=>Math.max(a,Math.min(b,Number(v)||0));
export const STATUS_TYPES=Object.freeze(['stun','slow','burn','poison','silence','vulnerable']);
function ensure(entity){if(!entity.combat98||typeof entity.combat98!=='object')entity.combat98={stagger:0,status:[],telegraph:null,phase:0};if(!Array.isArray(entity.combat98.status))entity.combat98.status=[];return entity.combat98}
export function activeStatuses(entity,now=Date.now()){const c=ensure(entity);c.status=c.status.filter(s=>Number(s.expiresAt)>now);return c.status}
export function hasStatus(entity,type,now=Date.now()){return activeStatuses(entity,now).some(s=>s.type===type)}
export function applyStatus(entity,type,durationMs,value=0,now=Date.now()){if(!STATUS_TYPES.includes(type))return false;const c=ensure(entity),duration=clamp(durationMs,100,30000);c.status=c.status.filter(s=>s.type!==type);c.status.push({type,value:clamp(value,-100,100),expiresAt:now+duration});return true}
export function addStagger(entity,amount,threshold=100,now=Date.now()){const c=ensure(entity);c.stagger=clamp(c.stagger+clamp(amount,0,100),0,200);if(c.stagger>=threshold){c.stagger=0;c.telegraph=null;applyStatus(entity,'stun',900,0,now);return {staggered:true,interrupted:true}}return {staggered:false,interrupted:false,stagger:c.stagger}}
export function beginTelegraph(monster,target,now=Date.now()){const c=ensure(monster);if(c.telegraph)return c.telegraph;const boss=monster.type==='boss',elite=monster.type==='elite';const windup=clamp(monster.telegraphMs??(boss?850:elite?650:420),200,2500);c.telegraph={kind:monster.telegraphKind||'strike',targetId:target.id,startedAt:now,resolveAt:now+windup,radius:clamp(monster.telegraphRadius??1,1,8),color:monster.telegraphColor||'#ff6b4a'};return c.telegraph}
export function resolveTelegraph(monster,target,now=Date.now()){const c=ensure(monster),t=c.telegraph;if(!t)return {ready:false};if(hasStatus(monster,'stun',now)||hasStatus(monster,'silence',now)){c.telegraph=null;return {ready:false,interrupted:true}}if(now<t.resolveAt)return {ready:false,telegraph:t};c.telegraph=null;return {ready:true,telegraph:t,targetMatches:t.targetId===target?.id}}
export function tickStatusDamage(entity,now=Date.now()){let damage=0;for(const s of activeStatuses(entity,now)){if(s.type==='burn'||s.type==='poison')damage+=Math.max(0,Math.floor(Math.abs(Number(s.value)||1)))}return damage}
export function publicCombatState(entity,now=Date.now()){const c=ensure(entity);return {stagger:Math.floor(c.stagger),telegraph:c.telegraph&&c.telegraph.resolveAt>now?{...c.telegraph}:null,status:activeStatuses(entity,now).map(s=>({type:s.type,value:s.value,expiresAt:s.expiresAt})),phase:c.phase||0}}
''')

write('server/engine/InteriorSystem.mjs', r'''// MOR'IA 9.8 — authoritative interior/door contract derived from maps + housing.
const key=(mapId,id)=>`${mapId}:${id}`;
const num=(v,f=0)=>Number.isFinite(Number(v))?Math.floor(Number(v)):f;
function normalizeRoom(raw,mapId,source='map'){if(!raw||typeof raw!=='object')return null;const id=String(raw.id||'').trim();if(!id)return null;const w=Math.max(3,Math.min(40,num(raw.width,8))),h=Math.max(3,Math.min(40,num(raw.height,8)));return {id,mapId,name:String(raw.name||id).slice(0,80),kind:String(raw.kind||source),width:w,height:h,entrance:{x:num(raw.entranceX,1),y:num(raw.entranceY,h-1)},exit:{x:num(raw.exitX,1),y:num(raw.exitY,h-1)},tiles:Array.isArray(raw.tiles)?raw.tiles.slice(0,w*h):[],props:Array.isArray(raw.props)?raw.props.slice(0,160):[],source}}
class InteriorSystem{
  constructor(){this.rooms=new Map()}
  sync(contentDB){this.rooms.clear();for(const map of contentDB?.get?.('maps')||[]){for(const raw of Array.isArray(map.interiors)?map.interiors:[]){const room=normalizeRoom(raw,map.id,'map');if(room)this.rooms.set(key(map.id,room.id),room)}}for(const house of contentDB?.get?.('houses')||[]){const room=normalizeRoom({id:`house_${house.id}`,name:house.name,kind:'house',width:house.width,height:house.height,entranceX:1,entranceY:Math.max(2,num(house.height,6)-1),exitX:1,exitY:Math.max(2,num(house.height,6)-1)},house.mapId,'housing');if(room)this.rooms.set(key(house.mapId,room.id),room)}}
  list(mapId){return [...this.rooms.values()].filter(r=>r.mapId===mapId).map(r=>({...r}))}
  get(mapId,id){const r=this.rooms.get(key(mapId,id));return r?{...r}:null}
  validate(room){if(!room)return 'interior is required';if(room.width<3||room.height<3)return 'interior must be at least 3x3';if(room.entrance.x<0||room.entrance.x>=room.width||room.entrance.y<0||room.entrance.y>=room.height)return 'entrance must be inside interior bounds';return null}
  enter(player,mapId,id){const room=this.rooms.get(key(mapId,id));const error=this.validate(room);if(error)return {ok:false,error};player.interior={mapId,id,x:room.entrance.x,y:room.entrance.y};return {ok:true,interior:{...room},position:{...room.entrance}}}
  exit(player){if(!player?.interior)return {ok:false,error:'not inside an interior'};const previous={...player.interior};delete player.interior;return {ok:true,previous}}
  snapshot(player){if(!player?.interior)return {inside:false};const room=this.get(player.interior.mapId,player.interior.id);return {inside:Boolean(room),room,position:room?{x:num(player.interior.x),y:num(player.interior.y)}:null}}
}
export const interiorSystem=new InteriorSystem();
''')

write('server/engine/WorldEventDirector.mjs', r'''// MOR'IA 9.8 — deterministic world-event scheduler/director.
export const EVENT_98_TYPES=Object.freeze(['invasion','world_boss','caravan','city_defense','weather','region','hunt','boss','defense']);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,Number(v)||0));
class WorldEventDirector{
 constructor(){this.active=new Map();this.lastActivation=new Map()}
 candidates(contentDB){return (contentDB?.get?.('worldEvents')||contentDB?.get?.('events')||[]).filter(e=>e&&EVENT_98_TYPES.includes(String(e.type||'hunt')))}
 shouldStart(event,now,clock){if(event.enabled===false)return false;const every=clamp(event.repeatEveryMs??0,0,7*24*3600e3);const last=this.lastActivation.get(event.id)||0;if(every&&now-last<every)return false;const hour=Number(clock?.hour);if(Number.isFinite(Number(event.startHour))&&Number.isFinite(hour)&&hour!==Number(event.startHour))return false;return Boolean(event.autoStart)||Boolean(every&&now-last>=every)}
 start(event,now=Date.now()){const duration=clamp(event.durationMs??600000,10000,6*3600e3);const state={id:event.id,name:event.name,type:event.type||'hunt',mapId:event.mapId||null,startedAt:now,endsAt:now+duration,phase:0,progress:0,needed:Math.max(1,Math.floor(Number(event.count)||1)),target:event.target||null,rewardGold:Math.max(0,Math.floor(Number(event.rewardGold)||0)),rewardXp:Math.max(0,Math.floor(Number(event.rewardXp)||0)),rewardCoins:Math.max(0,Math.floor(Number(event.rewardCoins)||0)),weather:event.weather||null,route:Array.isArray(event.route)?event.route:[],bossId:event.bossId||null};this.active.set(state.id,state);this.lastActivation.set(state.id,now);return state}
 stop(id){return this.active.delete(id)}
 tick({contentDB,clock,now=Date.now()}={}){for(const [id,state] of this.active)if(now>=state.endsAt)this.active.delete(id);for(const event of this.candidates(contentDB)){if(!this.active.has(event.id)&&this.shouldStart(event,now,clock))this.start(event,now)}for(const state of this.active.values()){const ratio=(now-state.startedAt)/Math.max(1,state.endsAt-state.startedAt);state.phase=Math.min(3,Math.floor(ratio*4))}return this.snapshot()}
 recordKill(mapId,monster){const updates=[];for(const state of this.active.values()){if(state.mapId&&state.mapId!==mapId)continue;if(state.target&&state.target!==monster?.name&&state.target!==monster?.contentId)continue;state.progress=Math.min(state.needed,state.progress+1);updates.push({...state,complete:state.progress>=state.needed})}return updates}
 snapshot(mapId=null){return [...this.active.values()].filter(e=>!mapId||!e.mapId||e.mapId===mapId).map(e=>({...e,route:e.route.map(p=>({...p}))}))}
}
export const worldEventDirector=new WorldEventDirector();
''')

write('server/engine/QuestFlowEngine.mjs', r'''// MOR'IA 9.8 — validates visual quest graphs while compiling to legacy objective contracts.
const IDS=/^[A-Za-z0-9_-]{1,100}$/;
export function normalizeQuestGraph(quest){const nodes=Array.isArray(quest?.nodes)?quest.nodes:[];return nodes.filter(n=>n&&IDS.test(String(n.id||''))).slice(0,64).map(n=>({id:String(n.id),type:String(n.type||'objective'),label:String(n.label||n.id).slice(0,100),target:n.target??null,count:Math.max(0,Math.floor(Number(n.count)||0)),dialogue:String(n.dialogue||'').slice(0,2000),event:n.event??null,x:Number(n.x)||0,y:Number(n.y)||0,next:Array.isArray(n.next)?n.next.filter(x=>IDS.test(String(x))).slice(0,8):[]}))}
export function validateQuestGraph(quest){const nodes=normalizeQuestGraph(quest);if(!nodes.length)return null;const ids=new Set(nodes.map(n=>n.id));for(const n of nodes)for(const to of n.next)if(!ids.has(to))return `quest node ${n.id} points to missing node ${to}`;const start=String(quest.startNode||nodes[0].id);if(!ids.has(start))return 'startNode is missing';const seen=new Set(),stack=[start];while(stack.length){const id=stack.pop();if(seen.has(id))continue;seen.add(id);const n=nodes.find(x=>x.id===id);for(const to of n?.next||[])stack.push(to)}if(seen.size!==nodes.length)return 'quest graph contains unreachable nodes';return null}
export function compileQuestGraph(quest){const nodes=normalizeQuestGraph(quest);const objectives=nodes.filter(n=>['objective','kill','collect','visit'].includes(n.type));const first=objectives[0];return {...quest,target:quest.target||first?.target||'',count:Number(quest.count)||first?.count||1,nodes,startNode:quest.startNode||nodes[0]?.id||null,branches:Array.isArray(quest.branches)?quest.branches.slice(0,32):[],triggers:Array.isArray(quest.triggers)?quest.triggers.slice(0,32):[]}}
export function nextQuestNodes(quest,currentId,context={}){const node=normalizeQuestGraph(quest).find(n=>n.id===currentId);if(!node)return[];return node.next.filter(id=>{const branch=(quest.branches||[]).find(b=>b.from===currentId&&b.to===id);if(!branch?.condition)return true;const value=context[branch.condition.key];return branch.condition.op==='gte'?Number(value)>=Number(branch.condition.value):branch.condition.op==='eq'?value===branch.condition.value:Boolean(value)})}
''')

