write('src/components/InteriorDesigner98.tsx', r'''import { useMemo,useState } from 'react';
type Room={id:string;name:string;kind:string;width:number;height:number;entranceX:number;entranceY:number;exitX:number;exitY:number;tiles:number[];props:any[]};
const blank=():Room=>({id:`interior_${Date.now()}`,name:'New Interior',kind:'house',width:10,height:8,entranceX:1,entranceY:7,exitX:1,exitY:7,tiles:[],props:[]});
export default function InteriorDesigner98(){const [rooms,setRooms]=useState<Room[]>(()=>{try{return JSON.parse(localStorage.getItem('moria_98_interiors')||'[]')}catch{return[]}});const [room,setRoom]=useState<Room>(rooms[0]||blank());const [paint,setPaint]=useState(1);const cells=useMemo(()=>Array.from({length:room.width*room.height},(_,i)=>room.tiles[i]||0),[room]);const save=(next:Room)=>{const all=[...rooms.filter(r=>r.id!==next.id),next];setRooms(all);setRoom(next);localStorage.setItem('moria_98_interiors',JSON.stringify(all))};const setCell=(i:number)=>{const tiles=[...cells];tiles[i]=paint;save({...room,tiles})};return <div className="grid gap-3 lg:grid-cols-[240px_1fr_250px]"><div className="space-y-2 rounded border border-cyan-400/30 bg-black/40 p-3"><div className="text-xs font-black tracking-widest text-cyan-200">INTERIOR DESIGNER 9.8</div><button className="w-full rounded bg-cyan-900/50 p-2 text-xs" onClick={()=>setRoom(blank())}>+ New interior</button>{rooms.map(r=><button key={r.id} onClick={()=>setRoom(r)} className="block w-full rounded border border-white/10 p-2 text-left text-xs">{r.name}</button>)}</div><div className="rounded border border-purple-400/25 bg-black/50 p-3"><div className="mb-2 flex gap-2 text-[10px]">{[['Floor',1],['Wall',2],['Door',3],['Prop',4]].map(([n,v])=><button key={String(n)} onClick={()=>setPaint(Number(v))} className={`rounded px-2 py-1 ${paint===v?'bg-purple-500':'bg-purple-950'}`}>{n}</button>)}</div><div className="grid gap-px bg-black" style={{gridTemplateColumns:`repeat(${room.width},minmax(18px,1fr))`}}>{cells.map((v,i)=><button key={i} onClick={()=>setCell(i)} className={`aspect-square border border-white/5 ${v===2?'bg-stone-700':v===3?'bg-amber-700':v===4?'bg-emerald-800':'bg-slate-900'}`} />)}</div></div><div className="space-y-2 rounded border border-purple-400/25 bg-black/40 p-3 text-xs"><label>Name<input className="mt-1 w-full bg-black p-2" value={room.name} onChange={e=>setRoom({...room,name:e.target.value})}/></label><label>Kind<select className="mt-1 w-full bg-black p-2" value={room.kind} onChange={e=>setRoom({...room,kind:e.target.value})}>{['house','tavern','shop','guild_hall','dungeon'].map(x=><option key={x}>{x}</option>)}</select></label><div className="grid grid-cols-2 gap-2"><label>Width<input type="number" min={3} max={40} className="w-full bg-black p-2" value={room.width} onChange={e=>setRoom({...room,width:+e.target.value})}/></label><label>Height<input type="number" min={3} max={40} className="w-full bg-black p-2" value={room.height} onChange={e=>setRoom({...room,height:+e.target.value})}/></label></div><button onClick={()=>save(room)} className="w-full rounded bg-emerald-700 p-2 font-bold">SAVE AUTHORING JSON</button><div className="text-[9px] text-purple-200/60">Entrances and bounds are revalidated by the authoritative InteriorSystem before runtime use.</div></div></div>}
''')

write('src/components/QuestGraphDesigner98.tsx', r'''import { useMemo,useState } from 'react';
type Node={id:string;type:string;label:string;x:number;y:number;target?:string;count?:number;dialogue?:string;next:string[]};
const make=(type='objective'):Node=>({id:`node_${Date.now()}`,type,label:type==='dialogue'?'Dialogue':'Objective',x:80,y:80,target:'',count:1,dialogue:'',next:[]});
export default function QuestGraphDesigner98(){const [nodes,setNodes]=useState<Node[]>([make('dialogue'),{...make('objective'),id:'objective_1',x:330,y:170,label:'Defeat enemies'}]);const [selected,setSelected]=useState(nodes[0].id);const [history,setHistory]=useState<Node[][]>([]);const node=nodes.find(n=>n.id===selected);const commit=(next:Node[])=>{setHistory(h=>[...h.slice(-19),nodes]);setNodes(next)};const update=(p:Partial<Node>)=>commit(nodes.map(n=>n.id===selected?{...n,...p}:n));const undo=()=>{const prev=history.at(-1);if(prev){setNodes(prev);setHistory(h=>h.slice(0,-1))}};const output=useMemo(()=>JSON.stringify({nodes,startNode:nodes[0]?.id,branches:[]},null,2),[nodes]);return <div className="grid gap-3 lg:grid-cols-[220px_1fr_300px]"><aside className="space-y-2 rounded border border-fuchsia-400/30 bg-black/40 p-3"><div className="text-xs font-black tracking-widest text-fuchsia-200">QUEST GRAPH 9.8</div>{['dialogue','objective','branch','reward','event'].map(t=><button key={t} onClick={()=>{const n={...make(t),x:120+nodes.length*25,y:90+nodes.length*20};commit([...nodes,n]);setSelected(n.id)}} className="block w-full rounded bg-fuchsia-950/50 p-2 text-left text-xs">+ {t}</button>)}<button onClick={undo} disabled={!history.length} className="w-full rounded bg-slate-800 p-2 text-xs">↶ Undo</button></aside><div className="relative min-h-[430px] overflow-hidden rounded border border-fuchsia-400/25 bg-[radial-gradient(circle_at_center,#28113d_0,#08040d_70%)]">{nodes.map(n=><button key={n.id} onClick={()=>setSelected(n.id)} style={{left:n.x,top:n.y}} className={`absolute w-36 rounded border p-2 text-left text-[10px] ${selected===n.id?'border-yellow-300 bg-purple-700':'border-purple-400/40 bg-black/70'}`}><b>{n.label}</b><div className="opacity-60">{n.type}</div></button>)}</div><aside className="space-y-2 rounded border border-purple-400/25 bg-black/40 p-3 text-xs">{node&&<><label>Label<input className="mt-1 w-full bg-black p-2" value={node.label} onChange={e=>update({label:e.target.value})}/></label><label>Target<input className="mt-1 w-full bg-black p-2" value={node.target||''} onChange={e=>update({target:e.target.value})}/></label><label>Count<input type="number" className="mt-1 w-full bg-black p-2" value={node.count||0} onChange={e=>update({count:+e.target.value})}/></label><label>Dialogue<textarea className="mt-1 h-20 w-full bg-black p-2" value={node.dialogue||''} onChange={e=>update({dialogue:e.target.value})}/></label><label>Next node<select className="mt-1 w-full bg-black p-2" onChange={e=>e.target.value&&update({next:[...new Set([...node.next,e.target.value])]})}><option value="">Connect…</option>{nodes.filter(n=>n.id!==node.id).map(n=><option key={n.id} value={n.id}>{n.label}</option>)}</select></label></>}<details><summary className="cursor-pointer text-purple-200">Compiled JSON</summary><pre className="mt-2 max-h-48 overflow-auto whitespace-pre-wrap text-[9px]">{output}</pre></details></aside></div>}
''')

write('src/components/WorldDirector98.tsx', r'''import { useState } from 'react';
const defaults={eventType:'invasion',autoStart:true,repeatEveryMs:3600000,durationMs:600000,aggroRadius:8,leashRadius:12,patrolRadius:3,telegraphMs:650,staggerThreshold:100};
export default function WorldDirector98(){const [cfg,setCfg]=useState(()=>{try{return {...defaults,...JSON.parse(localStorage.getItem('moria_98_world_director')||'{}')}}catch{return defaults}});const set=(k:string,v:any)=>setCfg((c:any)=>({...c,[k]:v}));const save=()=>localStorage.setItem('moria_98_world_director',JSON.stringify(cfg));return <div className="grid gap-3 md:grid-cols-3"><section className="rounded border border-emerald-400/25 bg-black/40 p-3"><h3 className="text-xs font-black tracking-widest text-emerald-200">NPC + MONSTER AI</h3>{[['Aggro radius','aggroRadius'],['Leash radius','leashRadius'],['Patrol radius','patrolRadius']].map(([l,k])=><label key={k} className="mt-3 block text-[10px]">{l}<input type="number" className="mt-1 w-full bg-black p-2" value={(cfg as any)[k]} onChange={e=>set(k,+e.target.value)}/></label>)}<div className="mt-3 text-[9px] text-emerald-100/60">Schedules, shop hours, patrol routes, guard radius, packs and flee thresholds are authored per NPC/monster in Content Studio.</div></section><section className="rounded border border-orange-400/25 bg-black/40 p-3"><h3 className="text-xs font-black tracking-widest text-orange-200">WORLD EVENTS 2.0</h3><label className="mt-3 block text-[10px]">Type<select className="mt-1 w-full bg-black p-2" value={(cfg as any).eventType} onChange={e=>set('eventType',e.target.value)}>{['invasion','world_boss','caravan','city_defense','weather','region'].map(x=><option key={x}>{x}</option>)}</select></label><label className="mt-3 block text-[10px]">Repeat ms<input type="number" className="mt-1 w-full bg-black p-2" value={(cfg as any).repeatEveryMs} onChange={e=>set('repeatEveryMs',+e.target.value)}/></label><label className="mt-3 block text-[10px]">Duration ms<input type="number" className="mt-1 w-full bg-black p-2" value={(cfg as any).durationMs} onChange={e=>set('durationMs',+e.target.value)}/></label></section><section className="rounded border border-red-400/25 bg-black/40 p-3"><h3 className="text-xs font-black tracking-widest text-red-200">COMBAT DEPTH</h3><label className="mt-3 block text-[10px]">Telegraph ms<input type="number" className="mt-1 w-full bg-black p-2" value={(cfg as any).telegraphMs} onChange={e=>set('telegraphMs',+e.target.value)}/></label><label className="mt-3 block text-[10px]">Stagger threshold<input type="number" className="mt-1 w-full bg-black p-2" value={(cfg as any).staggerThreshold} onChange={e=>set('staggerThreshold',+e.target.value)}/></label><div className="mt-3 text-[9px] text-red-100/60">Server owns telegraph resolution, stagger, interrupt and bounded status durations; UI only presents authoritative combat state.</div></section><button onClick={save} className="md:col-span-3 rounded bg-purple-700 p-3 text-xs font-black">SAVE 9.8 AUTHORING PRESET</button></div>}
''')

write('src/components/CityDesigner98.tsx', r'''import {useMemo,useRef,useState} from 'react';
import {MAPS,MAP_WIDTH,MAP_HEIGHT,syncServerMaps,type GameMap} from '../game/maps';
import {getCustomNPCs,getCustomMonsters} from '../game/content';
import InteriorDesigner98 from './InteriorDesigner98';
type Layer='buildings'|'npcs'|'monsters'|'portals'|'props'|'protected';
const clone=<T,>(x:T):T=>JSON.parse(JSON.stringify(x));const snap=(v:number,on:boolean)=>Math.max(1,Math.min(78,Math.round(on?v:Math.round(v))));
export default function CityDesigner98({onApplied}:{onApplied?:()=>void}){const ids=Object.keys(MAPS);const [mapId,setMapId]=useState(ids[0]||'eldoria');const [draft,setDraft]=useState<GameMap>(()=>clone(MAPS[ids[0]||'eldoria']));const [snapOn,setSnapOn]=useState(true);const [layers,setLayers]=useState<Record<Layer,boolean>>({buildings:true,npcs:true,monsters:true,portals:true,props:true,protected:true});const [history,setHistory]=useState<GameMap[]>([]);const [future,setFuture]=useState<GameMap[]>([]);const [selected,setSelected]=useState<any>(null);const [interiors,setInteriors]=useState(false);const ref=useRef<HTMLDivElement>(null);const npcs=getCustomNPCs().filter((n:any)=>n.mapId===mapId);const monsters=getCustomMonsters().filter((m:any)=>m.mapId===mapId);const commit=(next:GameMap)=>{setHistory(h=>[...h.slice(-29),clone(draft)]);setFuture([]);setDraft(next)};const undo=()=>{const p=history.at(-1);if(p){setFuture(f=>[clone(draft),...f]);setDraft(p);setHistory(h=>h.slice(0,-1))}};const redo=()=>{const n=future[0];if(n){setHistory(h=>[...h,clone(draft)]);setDraft(n);setFuture(f=>f.slice(1))}};const point=(e:any)=>{const r=ref.current!.getBoundingClientRect();return{x:snap(((e.clientX-r.left)/r.width)*MAP_WIDTH,snapOn),y:snap(((e.clientY-r.top)/r.height)*MAP_HEIGHT,snapOn)}};const moveLandmark=(id:string,p:any)=>commit({...draft,landmarks:draft.landmarks.map((l:any)=>l.id===id?{...l,x:Math.min(MAP_WIDTH-l.w-1,p.x),y:Math.min(MAP_HEIGHT-l.h-1,p.y)}:l)});const resize=(id:string,dw:number,dh:number)=>commit({...draft,landmarks:draft.landmarks.map((l:any)=>l.id===id?{...l,w:Math.max(2,Math.min(12,l.w+dw)),h:Math.max(2,Math.min(12,l.h+dh))}:l)});const apply=()=>{const records=Object.values(MAPS).map(m=>m.id===draft.id?clone(draft):clone(m));syncServerMaps(records);localStorage.setItem('moria_city_designer_maps',JSON.stringify(records));onApplied?.()};const protectedCount=useMemo(()=>draft.landmarks.reduce((n:any,l:any)=>n+l.w*l.h,0)+(draft.portals?.length||0)+1,[draft]);if(interiors)return <div><button onClick={()=>setInteriors(false)} className="mb-2 rounded bg-purple-800 px-3 py-2 text-xs">← City Designer 2.0</button><InteriorDesigner98/></div>;return <div className="space-y-3"><div className="flex flex-wrap items-center gap-2 rounded border border-cyan-400/30 bg-black/50 p-3"><b className="mr-auto text-xs tracking-widest text-cyan-200">CITY DESIGNER 2.0 · AUTHORITATIVE LAYERS</b><button onClick={undo} className="rounded bg-slate-800 px-2 py-1 text-xs">↶ Undo</button><button onClick={redo} className="rounded bg-slate-800 px-2 py-1 text-xs">↷ Redo</button><button onClick={()=>setSnapOn(!snapOn)} className={`rounded px-2 py-1 text-xs ${snapOn?'bg-emerald-700':'bg-slate-800'}`}>Snap</button><button onClick={()=>setInteriors(true)} className="rounded bg-purple-700 px-2 py-1 text-xs">Interiors</button><button onClick={apply} className="rounded bg-cyan-700 px-3 py-1 text-xs font-bold">Apply</button></div><div className="flex flex-wrap gap-2 text-[10px]">{(Object.keys(layers) as Layer[]).map(l=><label key={l} className="rounded border border-white/10 bg-black/40 px-2 py-1"><input type="checkbox" checked={layers[l]} onChange={()=>setLayers({...layers,[l]:!layers[l]})}/> {l}</label>)}<span className="rounded bg-red-950/60 px-2 py-1 text-red-200">No-build cells: {protectedCount}</span></div><select value={mapId} onChange={e=>{setMapId(e.target.value);setDraft(clone(MAPS[e.target.value]));setHistory([]);setFuture([])}} className="rounded bg-black p-2 text-xs">{ids.map(id=><option key={id} value={id}>{MAPS[id].name}</option>)}</select><div ref={ref} onPointerDown={e=>{if(selected?.type==='landmark')moveLandmark(selected.id,point(e))}} className="relative mx-auto aspect-square max-h-[620px] w-full max-w-[720px] overflow-hidden rounded border border-purple-400/30 bg-[linear-gradient(#17211b_1px,transparent_1px),linear-gradient(90deg,#17211b_1px,transparent_1px),#07100b] bg-[size:12px_12px]">{layers.protected&&<><div className="absolute h-4 w-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-red-400/80" style={{left:`${draft.spawnPoint.x/MAP_WIDTH*100}%`,top:`${draft.spawnPoint.y/MAP_HEIGHT*100}%`}}/><div className="absolute left-2 top-2 rounded bg-red-950/80 px-2 py-1 text-[9px] text-red-200">Protected overlay: spawn · portals · landmarks · housing contract</div></>}{layers.buildings&&draft.landmarks.map((l:any)=><div key={l.id} onPointerDown={e=>{e.stopPropagation();setSelected({type:'landmark',id:l.id})}} className={`absolute cursor-move border ${selected?.id===l.id?'border-yellow-300 bg-yellow-400/20':'border-cyan-400/50 bg-cyan-900/30'}`} style={{left:`${l.x/MAP_WIDTH*100}%`,top:`${l.y/MAP_HEIGHT*100}%`,width:`${l.w/MAP_WIDTH*100}%`,height:`${l.h/MAP_HEIGHT*100}%`}}><span className="absolute -top-4 whitespace-nowrap text-[8px]">{l.name}</span>{selected?.id===l.id&&<button title="Resize handle" onClick={e=>{e.stopPropagation();resize(l.id,1,1)}} className="absolute -bottom-1 -right-1 h-3 w-3 bg-yellow-300"/>}</div>)}{layers.portals&&draft.portals?.map((p:any,i:number)=><div key={i} className="absolute h-3 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full bg-fuchsia-500" style={{left:`${p.x/MAP_WIDTH*100}%`,top:`${p.y/MAP_HEIGHT*100}%`}} title="Portal"/>)}{layers.props&&draft.props.map((p:any)=><div key={p.id} className="absolute h-2 w-2 rounded-full bg-amber-300" style={{left:`${p.x/MAP_WIDTH*100}%`,top:`${p.y/MAP_HEIGHT*100}%`}}/>)}{layers.npcs&&npcs.map((n:any)=><div key={n.id} className="absolute -translate-x-1/2 -translate-y-1/2 text-sm" style={{left:`${n.posX/MAP_WIDTH*100}%`,top:`${n.posY/MAP_HEIGHT*100}%`}} title={`${n.name} · ${n.aiMode||'idle'}`}>{n.emoji||'🧙'}</div>)}{layers.monsters&&monsters.map((m:any)=><div key={m.id} className="absolute -translate-x-1/2 -translate-y-1/2 text-sm" style={{left:`${m.posX/MAP_WIDTH*100}%`,top:`${m.posY/MAP_HEIGHT*100}%`}} title={`${m.name} · ${m.aiArchetype||m.type||'normal'}`}>{m.emoji||'👹'}</div>)}</div><div className="text-[10px] text-purple-100/60">Drag/select buildings on the canvas; resize from the yellow handle. Layer visibility, snap, undo/redo, interiors and protected-space overlays are live. NPC/monster coordinates remain Content Studio authored and server authoritative.</div></div>}
''')

